1	import { describe, it, expect } from "vitest";
2	import { scoreDocument } from "./cli.js";
3	
4	describe("Sphinx scoring CLI", () => {
5	  it('scores an input document into an output document — {"army":[]} yields {"score":0}', () => {
6	    expect(scoreDocument('{"army":[]}')).toBe('{"score":0}');
7	  });
8	  it.todo("delegates scoring to the army rules — the spec's example document yields {\"score\":2}");
9	  it.todo("passes Undead Warrior rank through to the scorer — variants count as one type");
10	  it.todo("runs as `pnpm exec tsx src/cli.ts`, reading stdin and writing the score to stdout");
11	});
