1	export type Card = {
2	  monster: string;
3	  rank?: number;
4	};
5	
6	const SPHINX = "sphinx";
7	
8	// A card's type is its monster alone — variants of the same monster
9	// (e.g. Undead Warrior ranks) all count as one type.
10	const typeOf = (card: Card): string => card.monster;
11	
12	const countDistinctTypes = (army: Card[]): number =>
13	  new Set(army.map(typeOf)).size;
14	
15	const NO_SPHINX_SCORE = 0;
16	const FREE_TYPES = 3;
17	const SCORE_WITHIN_FREE_TYPES = 2;
18	const BASE_SCORE_BEYOND_FREE_TYPES = 1;
19	const POINTS_PER_EXTRA_TYPE = 2;
20	
21	const scoreOneSphinx = (visibleTypeCount: number): number => {
22	  if (visibleTypeCount <= FREE_TYPES) return SCORE_WITHIN_FREE_TYPES;
23	
24	  const extraTypes = visibleTypeCount - FREE_TYPES;
25	  return BASE_SCORE_BEYOND_FREE_TYPES + POINTS_PER_EXTRA_TYPE * extraTypes;
26	};
27	
28	// A Sphinx counts the types it sees among the *other* cards, so it never
29	// counts its own type — unless a second Sphinx card is there to supply it.
30	const countTypesVisibleToASphinx = (
31	  army: Card[],
32	  sphinxCount: number,
33	): number => {
34	  const anotherSphinxSuppliesTheSphinxType = sphinxCount > 1;
35	  const visibleArmy = anotherSphinxSuppliesTheSphinxType
36	    ? army
37	    : army.filter((card) => typeOf(card) !== SPHINX);
38	  return countDistinctTypes(visibleArmy);
39	};
40	
41	export const scoreArmy = (army: Card[]): number => {
42	  const sphinxCount = army.filter((card) => typeOf(card) === SPHINX).length;
43	  if (sphinxCount === 0) return NO_SPHINX_SCORE;
44	
45	  const visibleTypes = countTypesVisibleToASphinx(army, sphinxCount);
46	  return sphinxCount * scoreOneSphinx(visibleTypes);
47	};
